using System;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "AstriumActivatedActionOmenData", menuName = "Data/Battle/Omens System/Omen Data/Orion/AstriumActivatedAction Omen Data")]
public class AstriumActivatedActionOmenData : AstriumActivatedOmenData
{
	protected override Action GetOmenAction(OmenInstance omenInstance)
	{
		return delegate
		{
			ActivateOmen();
			omenInstance.EnqueueOmenFeedbackAndPlay();
		};
	}
}
